function c = balance_chem(A)
    N = null(A, 'r');
    if size(N, 2) ~= 1
        error('零空间维数不为 1 (dim = %d), 化学方程式无唯一最简配平。', size(N, 2));
    end
    v = N(:, 1);
    if v(1) < 0
        v = -v;
    end
    [~, den] = rat(v, 1e-12);
    L = 1;
    for k = 1:numel(den)
        L = lcm(L, den(k));
    end
    c = round(v * L);
    g = abs(c(1));
    for k = 2:numel(c)
        g = gcd(g, abs(c(k)));
    end
    c = c / g;
    if any(c <= 0)
        error('所得系数不全为正, 请检查化学反应矩阵正负号或可配平性。');
    end
end
```

**分析说明**：
- `balance_chem` 先求元素守恒矩阵 $\boldsymbol A$ 零空间的一维有理基，再用 `rat` 提取各分母并逐步求最小公倍数 `lcm` 化为整数向量，最后除以各分量的最大公约数 `gcd` 得到互素的最简正整数系数。
