function [rk, x, has_sol] = gf2_solve(A, b)
    % 在 K_2 上对 [A | b] 作 Gauss-Jordan 消元, 返回秩、一个特解与是否有解
    A = mod(round(A), 2);
    b = mod(round(b(:)), 2);
    [m, n] = size(A);
    Aug = [A, b];
    r = 1;
    piv_cols = zeros(1, min(m, n));
    rk = 0;
    for col = 1:n
        piv = find(Aug(r:m, col) == 1, 1, 'first');
        if isempty(piv)
            continue;
        end
        piv = piv + r - 1;
        if piv ~= r
            Aug([r, piv], :) = Aug([piv, r], :);
        end
        for row = 1:m
            if row ~= r && Aug(row, col) == 1
                Aug(row, :) = xor(Aug(row, :), Aug(r, :));
            end
        end
        rk = rk + 1;
        piv_cols(rk) = col;
        r = r + 1;
        if r > m
            break;
        end
    end
    has_sol = all(Aug(rk+1:m, n+1) == 0);
    x = zeros(n, 1);
    if has_sol
        for k = 1:rk
            x(piv_cols(k)) = Aug(k, n+1);
        end
    end
end
```

**分析说明**：
- 对一维情形 $n=1,\cdots,30$，程序精确验证 $\boldsymbol L_n$ 在 $\mathbb K_2$ 上不可逆当且仅当 $n=2,5,8,11,14,17,20,23,26,29$（即 $n\equiv 2\pmod 3$），与习题 6.C.6 (1) 完全吻合。
