function M = build_tomo_matrix(n, dirs)
    rows = {};
    [C, R] = meshgrid(1:n, 1:n);
    for d = 1:size(dirs, 1)
        a = dirs(d, 1); b = dirs(d, 2);
        vals = a * R + b * C;
        uvals = unique(vals(:));
        for k = 1:numel(uvals)
            mask = double(vals == uvals(k));
            rows{end+1} = mask(:)'; %#ok<AGROW>
        end
    end
    M = cell2mat(rows');
end
